const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const META='hestia-disk-revisions-v1';
export function mountLocalWorkspace(bridge){let online=false,pending=null,busy=false,timer,stopped=false,conflict=false;let revisions={};try{revisions=JSON.parse(localStorage.getItem(META)||'{}');}catch{}const contents=new Map();const status=document.querySelector('#save-status');
const setStatus=message=>{status.textContent=message;};
function remember(key,revision){revisions[key]=revision;try{localStorage.setItem(META,JSON.stringify(revisions));}catch{}}
async function api(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json','X-Hestia-Client':'studio',...options.headers}});const body=await response.json();if(!response.ok){const error=new Error(body.error||'Local workspace request failed.');error.status=response.status;throw error;}return body;}
const key=id=>'projects/'+id;
const comparable=p=>{const c=structuredClone(p);delete c.updatedAt;return JSON.stringify(c);};
async function baseRevision(document){if(revisions[key(document.id)]!==undefined)return revisions[key(document.id)];try{const saved=await api('/api/projects/'+encodeURIComponent(document.id));if(comparable(saved.data)!==comparable(document)){const error=new Error('This PC has a different saved version. Open PC workspace to load it, or save your browser version as a copy.');error.status=409;throw error;}remember(key(document.id),saved.revision);return saved.revision;}catch(error){if(error.status===404){remember(key(document.id),0);return 0;}throw error;}}
async function drain(){if(!online||busy||stopped||conflict||!pending)return;busy=true;while(pending&&!conflict&&!stopped){const document=pending;pending=null;setStatus('Saving to PC…');try{const expected=await baseRevision(document);const saved=await api('/api/projects/'+encodeURIComponent(document.id),{method:'PUT',headers:{'If-Match':String(expected)},body:JSON.stringify({document})});remember(key(document.id),saved.revision);if(bridge.getProject().id===document.id)setStatus('Saved on PC · revision '+saved.revision);}catch(error){if(!pending)pending=document;conflict=error.status===409;stopped=!conflict;setStatus(conflict?'Save conflict · open PC workspace':'PC save failed · browser recovery kept');bridge.toast(error.message);break;}}busy=false;}
function queue(document){if(!online)return;const content=comparable(document);if(contents.get(document.id)===content){if(pending&&!stopped&&!conflict){clearTimeout(timer);timer=setTimeout(drain,450);}else if(!busy&&!conflict&&!stopped)setStatus('Saved on PC · revision '+(revisions[key(document.id)]||1));return;}contents.set(document.id,content);pending=structuredClone(document);clearTimeout(timer);if(conflict)setStatus('Save conflict · open PC workspace');else if(stopped)setStatus('PC save stopped · open workspace');else{setStatus('Saving to PC…');timer=setTimeout(drain,450);}}
async function flush(){clearTimeout(timer);await drain();while(busy)await new Promise(r=>setTimeout(r,25));}
async function load(id){await flush();const saved=await api('/api/projects/'+encodeURIComponent(id));conflict=false;stopped=false;pending=null;remember(key(id),saved.revision);contents.set(id,comparable(saved.data));bridge.replaceProject(saved.data);setStatus('Saved on PC · revision '+saved.revision);document.querySelector('#modal').close();bridge.toast('Opened the project saved on this PC.');}
async function copy(){const document=structuredClone(bridge.getProject());document.id=crypto.randomUUID();document.name=(document.name+' copy').slice(0,100);conflict=false;stopped=false;pending=null;remember(key(document.id),0);bridge.replaceProject(document);await flush();await openDialog();}
async function history(id){await flush();const result=await api('/api/projects/'+encodeURIComponent(id)+'/history');bridge.modal(`<span class="eyebrow">RECOVERY HISTORY</span><h2>Earlier versions</h2><p>Restoring creates a new revision. It does not erase the existing history. The latest 20 revisions are retained.</p><div class="export-options">${result.revisions.map(r=>`<button class="export-option" data-restore="${r.revision}"><span><strong>Revision ${r.revision}</strong><small>${esc(new Date(r.updatedAt).toLocaleString())} · ${esc(r.name)}</small></span></button>`).join('')||'<p>No saved revisions yet.</p>'}</div>`);for(const button of document.querySelectorAll('[data-restore]'))button.onclick=async()=>{bridge.confirm('Restore revision '+button.dataset.restore+'?','The current project will be replaced with this saved version and stored as a new revision.',async()=>{try{const latest=await api('/api/projects/'+encodeURIComponent(id));const restored=await api('/api/projects/'+encodeURIComponent(id)+'/restore',{method:'POST',headers:{'If-Match':String(latest.revision)},body:JSON.stringify({revision:Number(button.dataset.restore)})});remember(key(id),restored.revision);conflict=false;stopped=false;pending=null;contents.set(id,comparable(restored.data));bridge.replaceProject(restored.data);bridge.toast('Restored revision '+button.dataset.restore+' as a new saved version.');}catch(error){bridge.toast(error.message);}});};}
async function openDialog(){try{const result=await api('/api/projects');bridge.modal(`<span class="eyebrow">SAVED ON THIS COMPUTER</span><h2>PC workspace</h2><p>Projects and reusable model components are stored by the local Node server. This workspace is for this PC; it is not a shared cloud account.</p>${conflict?'<p class="workspace-warning">Another version exists on disk. Open that version or save your browser changes as a separate copy.</p>':''}<div class="dialog-actions"><button id="disk-save-now" class="button primary">Save current project</button><button id="disk-save-copy" class="button subtle">Save as a new copy</button></div><div class="export-options">${result.documents.map(r=>`<div class="project-option"><div><strong>${esc(r.name)}</strong><small>Revision ${r.revision} · ${esc(new Date(r.updatedAt).toLocaleString())}</small></div><button class="button subtle" data-disk-open="${esc(r.id)}">Open</button><button class="icon-btn" title="Recovery history" aria-label="History of ${esc(r.name)}" data-disk-history="${esc(r.id)}">↶</button></div>`).join('')||'<p>No projects saved on this PC yet.</p>'}</div><p>Keep using editable project exports for portable backups. The server stores workspace files in <code>.hestia-data</code>, or your configured <code>HESTIA_DATA_DIR</code>.</p>`);document.querySelector('#disk-save-now').onclick=async()=>{if(conflict){bridge.toast('Open the saved version or save a copy to resolve the conflict.');return;}stopped=false;queue(bridge.getProject());await flush();if(!stopped&&!conflict)await openDialog();};document.querySelector('#disk-save-copy').onclick=()=>copy().catch(e=>bridge.toast(e.message));for(const b of document.querySelectorAll('[data-disk-open]'))b.onclick=()=>bridge.confirm('Open this saved project?','Export a backup first if you want to keep unsaved browser changes.',()=>load(b.dataset.diskOpen).catch(e=>bridge.toast(e.message)));for(const b of document.querySelectorAll('[data-disk-history]'))b.onclick=()=>history(b.dataset.diskHistory).catch(e=>bridge.toast(e.message));}catch(error){bridge.toast(error.message);}}
async function saveComponent(definition){if(!online)throw Error('Start Hestia with npm start to use the PC component library.');const k='components/'+definition.id;let revision=revisions[k];if(revision===undefined){try{await api('/api/components/'+encodeURIComponent(definition.id));throw Error('That component already exists on this PC. Make a unique component before saving it.');}catch(error){if(error.status!==404)throw error;revision=0;}}const result=await api('/api/components/'+encodeURIComponent(definition.id),{method:'PUT',headers:{'If-Match':String(revision)},body:JSON.stringify({document:definition})});remember(k,result.revision);return result;}
async function components(){if(!online)throw Error('Start Hestia with npm start to use the PC component library.');return(await api('/api/components')).documents;}
async function component(id){const r=await api('/api/components/'+encodeURIComponent(id));remember('components/'+id,r.revision);return r.data;}
fetch('/api/health').then(r=>r.ok?r.json():null).then(health=>{if(health?.mode!=='local'||health.storage!=='disk')return;online=true;const button=document.createElement('button');button.className='button subtle';button.id='pc-workspace-btn';button.textContent='PC workspace';button.onclick=openDialog;document.querySelector('.header-actions').prepend(button);queue(bridge.getProject());bridge.render?.();}).catch(()=>{});
window.addEventListener('beforeunload',e=>{if(online&&(pending||busy)){e.preventDefault();e.returnValue='';}});
return{queue,flush,openDialog,saveComponent,components,component,get online(){return online;}};
}
